\begin{tikzpicture}[font=\small]
% 定义颜色
\definecolor{coal}{RGB}{205, 92, 92}    % 煤炭
\definecolor{oil}{RGB}{255, 165, 0}     % 石油
\definecolor{gas}{RGB}{255, 255, 0}     % 天然气
\definecolor{nonfossil}{RGB}{144, 238, 144} % 非化石能源

% 饼图绘制
% 总角度 360
% 煤炭: 55.3% -> 200.58度
% 石油: 18.7% -> 67.32度
% 天然气: 8.9% -> 32.04度
% 非化石: 17.1% -> 61.56度

\begin{scope}[shift={(0,0)}]
    % 绘制煤炭扇区
    \fill[coal] (0,0) -- (0:2.5cm) arc (0:200.58:2.5cm) -- cycle;
    \node[anchor=south east, font=\scriptsize, text=white, align=center] at (200.58/2:1.8cm) {煤炭\\55.3\%};

    % 绘制石油扇区
    \fill[oil] (0,0) -- (200.58:2.5cm) arc (200.58:267.9:2.5cm) -- cycle;
    \node[anchor=south west, font=\scriptsize, text=white, align=center] at (234.24:1.8cm) {石油\\18.7\%};

    % 绘制天然气扇区
    \fill[gas] (0,0) -- (267.9:2.5cm) arc (267.9:299.94:2.5cm) -- cycle;
    \node[anchor=west, font=\scriptsize, text=black, align=center] at (283.92:1.8cm) {天然气\\8.9\%};

    % 绘制非化石能源扇区
    \fill[nonfossil] (0,0) -- (299.94:2.5cm) arc (299.94:360:2.5cm) -- cycle;
    \node[anchor=north west, font=\scriptsize, text=black, align=center] at (330:1.8cm) {非化石\\17.1\%};
\end{scope}

% 标题
\node[anchor=south, font=\bfseries, yshift=0.5cm] at (0, 2.5) {2023年中国能源消费结构};

% 图例 (外置右侧，符合 R1)
\node[anchor=west, font=\small] at (3.0, 1.5) {\color{coal}\Large$\blacksquare$ 煤炭 (55.3\%)};
\node[anchor=west, font=\small] at (3.0, 1.0) {\color{oil}\Large$\blacksquare$ 石油 (18.7\%)};
\node[anchor=west, font=\small] at (3.0, 0.5) {\color{gas}\Large$\blacksquare$ 天然气 (8.9\%)};
\node[anchor=west, font=\small] at (3.0, 0.0) {\color{nonfossil}\Large$\blacksquare$ 非化石能源 (17.1\%)};

% 数据来源注记 (符合 R2)
\node[anchor=north west, font=\scriptsize] at (0, -2.8) {数据来源：国家统计局 (2023年)};

\end{tikzpicture}
```

